struct MSTEdge { int from, to; long long weight; int id; };
struct MSTResult {
    long long weight = 0;
    vector<int> edge_ids;
    int components = 0;
    bool connected() const { return components <= 1; }
};
MSTResult kruskal(int n, vector<MSTEdge> edges) {
    sort(edges.begin(), edges.end(), [](const MSTEdge& a, const MSTEdge& b) {
        return tie(a.weight, a.id) < tie(b.weight, b.id);
    });
    DSU sets(n);
    MSTResult result;
    for (const auto& edge : edges) {
        if (!sets.unite(edge.from, edge.to)) continue;
        result.weight += edge.weight;
        result.edge_ids.push_back(edge.id);
        if (sets.components == 1) break;
    }
    result.components = sets.components;
    return result;
}

templates.example:
int main() {
    vector<MSTEdge> edges = {{0,1,3,0}, {1,2,-1,1}, {0,2,5,2}, {1,1,-9,3}};
    auto result = kruskal(3, edges);
    assert(result.connected() && result.weight == 2 && result.edge_ids.size() == 2);
    assert(!kruskal(4, edges).connected());
}

