#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct BFSResult { vector<int> distance, parent; };
BFSResult bfs(const vector<vector<int>>& graph, const vector<int>& sources) {
    int n = graph.size();
    BFSResult result{vector<int>(n, -1), vector<int>(n, -1)};
    queue<int> pending;
    for (int source : sources) {
        if (result.distance[source] != -1) continue;
        result.distance[source] = 0; pending.push(source);
    }
    while (!pending.empty()) {
        int vertex = pending.front(); pending.pop();
        for (int next : graph[vertex]) {
            if (result.distance[next] != -1) continue;
            result.distance[next] = result.distance[vertex] + 1;
            result.parent[next] = vertex;
            pending.push(next);
        }
    }
    return result;
}

