#include <bits/stdc++.h>
#include <cassert>
using namespace std;

vector<int> zero_one_bfs(const vector<vector<pair<int,int>>>& graph, int source) {
    int n = graph.size();
    const int INF = numeric_limits<int>::max() / 2;
    vector<int> distance(n, INF);
    deque<pair<int,int>> pending;
    distance[source] = 0; pending.push_front({0,source});
    while (!pending.empty()) {
        auto [current, vertex] = pending.front(); pending.pop_front();
        if (current != distance[vertex]) continue;
        for (auto [next, weight] : graph[vertex]) {
            assert(weight == 0 || weight == 1);
            if (current + weight >= distance[next]) continue;
            distance[next] = current + weight;
            if (weight == 0) pending.push_front({distance[next], next});
            else pending.push_back({distance[next], next});
        }
    }
    return distance;
}

