#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct BFEdge { int from, to; long long weight; };
struct BFResult { vector<long long> distance; vector<bool> negative; };
BFResult bellman_ford(int n, const vector<BFEdge>& edges, int source) {
    constexpr long long INF = numeric_limits<long long>::max() / 4;
    vector<__int128> distance(n, (__int128)INF);
    vector<vector<int>> graph(n);
    for (auto edge : edges) graph[edge.from].push_back(edge.to);
    distance[source] = 0;
    vector<bool> negative(n, false);
    queue<int> pending;
    for (int round = 0; round < n; ++round) {
        bool changed = false;
        for (auto edge : edges) {
            if (distance[edge.from] == INF) continue;
            __int128 candidate = distance[edge.from] + edge.weight;
            if (candidate >= distance[edge.to]) continue;
            distance[edge.to] = candidate;
            changed = true;
            if (round == n-1 && !negative[edge.to]) {
                negative[edge.to] = true; pending.push(edge.to);
            }
        }
        if (!changed) break;
    }
    while (!pending.empty()) {
        int vertex = pending.front(); pending.pop();
        for (int next : graph[vertex]) if (!negative[next]) {
            negative[next] = true; pending.push(next);
        }
    }
    BFResult result{vector<long long>(n, INF), negative};
    for (int v=0; v<n; ++v) if (!negative[v] && distance[v] != INF) {
        assert(-(__int128)INF < distance[v] && distance[v] < INF);
        result.distance[v] = (long long)distance[v];
    }
    return result;
}

templates.example:
int main() {
    auto finite = bellman_ford(3, {{0,1,4},{1,2,-2}}, 0);
    assert(finite.distance[2] == 2 && !finite.negative[2]);
    auto cycle = bellman_ford(4, {{0,1,1},{1,2,-2},{2,1,1}}, 0);
    assert(cycle.negative[1] && cycle.negative[2] && !cycle.negative[3]);
}

