#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct SCCResult { vector<int> component; vector<vector<int>> groups, dag; };
SCCResult strongly_connected_components(const vector<vector<int>>& graph) {
    int n = graph.size();
    vector<vector<int>> reverse_graph(n);
    for (int v=0; v<n; ++v) for (int next : graph[v]) reverse_graph[next].push_back(v);
    vector<bool> visited(n, false);
    vector<int> order;
    for (int start=0; start<n; ++start) if (!visited[start]) {
        vector<pair<int,size_t>> stack{{start,0}}; visited[start] = true;
        while (!stack.empty()) {
            int vertex = stack.back().first;
            size_t& edge_index = stack.back().second;
            if (edge_index == graph[vertex].size()) {
                order.push_back(vertex); stack.pop_back(); continue;
            }
            int next = graph[vertex][edge_index++];
            if (!visited[next]) { visited[next] = true; stack.push_back({next,0}); }
        }
    }
    SCCResult result{vector<int>(n,-1), {}, {}};
    reverse(order.begin(), order.end());
    for (int start : order) if (result.component[start] == -1) {
        int id = result.groups.size(); result.groups.push_back({});
        vector<int> stack{start}; result.component[start] = id;
        while (!stack.empty()) {
            int vertex = stack.back(); stack.pop_back(); result.groups[id].push_back(vertex);
            for (int next : reverse_graph[vertex]) if (result.component[next] == -1) {
                result.component[next] = id; stack.push_back(next);
            }
        }
    }
    result.dag.resize(result.groups.size());
    for (int v=0; v<n; ++v) for (int next : graph[v])
        if (result.component[v] != result.component[next])
            result.dag[result.component[v]].push_back(result.component[next]);
    for (auto& edges : result.dag) {
        sort(edges.begin(), edges.end());
        edges.erase(unique(edges.begin(), edges.end()), edges.end());
    }
    return result;
}

