#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct LCA {
    int levels = 1;
    vector<vector<int>> ancestor;
    vector<int> depth, component;
    explicit LCA(const vector<vector<int>>& forest) {
        int n = forest.size();
        while ((1LL << levels) <= max(1,n)) ++levels;
        ancestor.assign(levels, vector<int>(n,-1));
        depth.assign(n,0); component.assign(n,-1);
        for (int root=0; root<n; ++root) if (component[root] == -1) {
            queue<int> pending; pending.push(root); component[root] = root;
            while (!pending.empty()) {
                int vertex = pending.front(); pending.pop();
                for (int next : forest[vertex]) if (component[next] == -1) {
                    component[next] = root; depth[next] = depth[vertex]+1;
                    ancestor[0][next] = vertex; pending.push(next);
                }
            }
        }
        for (int level=1; level<levels; ++level) for (int v=0; v<n; ++v) {
            int middle = ancestor[level-1][v];
            if (middle != -1) ancestor[level][v] = ancestor[level-1][middle];
        }
    }
    int kth_ancestor(int vertex, long long steps) const {
        if (steps < 0 || steps > depth[vertex]) return -1;
        for (int level=0; level<levels; ++level)
            if ((steps >> level) & 1LL) vertex = ancestor[level][vertex];
        return vertex;
    }
    int query(int a, int b) const {
        if (component[a] != component[b]) return -1;
        if (depth[a] < depth[b]) swap(a,b);
        a = kth_ancestor(a,depth[a]-depth[b]);
        if (a == b) return a;
        for (int level=levels-1; level>=0; --level) if (ancestor[level][a] != ancestor[level][b]) {
            a = ancestor[level][a]; b = ancestor[level][b];
        }
        return ancestor[0][a];
    }
    int distance(int a,int b) const {
        int common = query(a,b);
        return common == -1 ? -1 : depth[a]+depth[b]-2*depth[common];
    }
};

templates.example:
int main() {
    LCA tree({{1,2},{0,3},{0},{1},{}});
    assert(tree.query(3,2) == 0 && tree.distance(3,2) == 3);
    assert(tree.kth_ancestor(3,2) == 0 && tree.kth_ancestor(3,3) == -1);
    assert(tree.query(3,4) == -1);
}

