#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct RangeAddSum {
    int n;
    vector<long long> sum, lazy;
    explicit RangeAddSum(const vector<long long>& values) : n(values.size()),
        sum(4*max(1,n),0), lazy(4*max(1,n),0) { if (n) build(1,0,n,values); }
    void build(int node,int left,int right,const vector<long long>& values) {
        if (right-left == 1) { sum[node]=values[left]; return; }
        int middle=left+(right-left)/2;
        build(node*2,left,middle,values); build(node*2+1,middle,right,values);
        pull(node);
    }
    void pull(int node) { sum[node]=sum[node*2]+sum[node*2+1]; }
    void apply(int node,int length,long long delta) {
        sum[node]+=delta*length; lazy[node]+=delta;
    }
    void push(int node,int left,int middle,int right) {
        apply(node*2,middle-left,lazy[node]);
        apply(node*2+1,right-middle,lazy[node]); lazy[node]=0;
    }
    void update(int node,int left,int right,int from,int to,long long delta) {
        if (to<=left || right<=from) return;
        if (from<=left && right<=to) { apply(node,right-left,delta); return; }
        int middle=left+(right-left)/2; push(node,left,middle,right);
        update(node*2,left,middle,from,to,delta);
        update(node*2+1,middle,right,from,to,delta); pull(node);
    }
    long long query(int node,int left,int right,int from,int to) {
        if (to<=left || right<=from) return 0;
        if (from<=left && right<=to) return sum[node];
        int middle=left+(right-left)/2; push(node,left,middle,right);
        return query(node*2,left,middle,from,to)+query(node*2+1,middle,right,from,to);
    }
    void add(int left,int right,long long delta) {
        assert(0<=left && left<=right && right<=n);
        if (left<right) update(1,0,n,left,right,delta);
    }
    long long range_sum(int left,int right) {
        assert(0<=left && left<=right && right<=n);
        return left==right ? 0 : query(1,0,n,left,right);
    }
};

templates.example:
int main() {
    RangeAddSum values({1,2,3,4}); values.add(1,4,5);
    assert(values.range_sum(0,4) == 25 && values.range_sum(2,3) == 8);
    values.add(0,2,-2); assert(values.range_sum(0,2) == 4);
    RangeAddSum empty({}); assert(empty.range_sum(0,0) == 0);
}

