#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct SparseMin {
    vector<int> logarithm;
    vector<vector<long long>> table;
    explicit SparseMin(const vector<long long>& values) {
        int n=values.size(); logarithm.assign(n+1,0);
        for (int i=2; i<=n; ++i) logarithm[i]=logarithm[i/2]+1;
        if (!n) return;
        table.assign(logarithm[n]+1,vector<long long>(n)); table[0]=values;
        for (int level=1; level<(int)table.size(); ++level)
            for (int left=0; left+(1<<level)<=n; ++left)
                table[level][left]=min(table[level-1][left],table[level-1][left+(1<<(level-1))]);
    }
    long long query(int left,int right) const { // [left,right)，非空
        assert(0<=left && left<right && right<(int)logarithm.size());
        int level=logarithm[right-left];
        return min(table[level][left],table[level][right-(1<<level)]);
    }
};

#include <bits/stdc++.h>
#include <cassert>
using namespace std;

template<class T> struct Compression {
    vector<T> values;
    explicit Compression(vector<T> input) : values(move(input)) {
        sort(values.begin(),values.end());
        values.erase(unique(values.begin(),values.end()),values.end());
    }
    int lower(const T& value) const {
        return lower_bound(values.begin(),values.end(),value)-values.begin();
    }
    int upper(const T& value) const {
        return upper_bound(values.begin(),values.end(),value)-values.begin();
    }
    int index(const T& value) const { // 必须已收集该原值
        int position=lower(value);
        assert(position<(int)values.size() && values[position]==value);
        return position;
    }
    const T& original(int index) const { return values.at(index); }
    int size() const { return values.size(); }
};

