#include <bits/stdc++.h>
#include <cassert>
using namespace std;

vector<long long> sliding_minimum(const vector<long long>& values,int width) {
    int n=values.size();
    if (width<=0 || width>n) return {};
    deque<int> pending; vector<long long> result;
    for (int right=0; right<n; ++right) {
        while (!pending.empty() && pending.front()<=right-width) pending.pop_front();
        while (!pending.empty() && values[pending.back()]>=values[right]) pending.pop_back();
        pending.push_back(right);
        if (right+1>=width) result.push_back(values[pending.front()]);
    }
    return result;
}

