#include <bits/stdc++.h>
#include <cassert>
using namespace std;

vector<int> prefix_function(const string& pattern) {
    int n=pattern.size(); vector<int> prefix(n,0);
    for (int i=1; i<n; ++i) {
        int length=prefix[i-1];
        while (length>0 && pattern[i]!=pattern[length]) length=prefix[length-1];
        if (pattern[i]==pattern[length]) ++length;
        prefix[i]=length;
    }
    return prefix;
}
vector<int> kmp_matches(const string& text,const string& pattern) {
    vector<int> result;
    if (pattern.empty()) {
        result.resize(text.size()+1); iota(result.begin(),result.end(),0); return result;
    }
    auto prefix=prefix_function(pattern); int matched=0;
    for (int i=0; i<(int)text.size(); ++i) {
        while (matched>0 && text[i]!=pattern[matched]) matched=prefix[matched-1];
        if (text[i]==pattern[matched]) ++matched;
        if (matched==(int)pattern.size()) {
            result.push_back(i-matched+1); matched=prefix[matched-1];
        }
    }
    return result;
}

