#include <bits/stdc++.h>
#include <cassert>
using namespace std;

vector<int> z_function(const string& text) {
    int n=text.size(); vector<int> z(n,0);
    if (n) z[0]=n;
    for (int i=1,left=0,right=0; i<n; ++i) { // 已知区间 [left,right)
        if (i<right) z[i]=min(right-i,z[i-left]);
        while (i+z[i]<n && text[z[i]]==text[i+z[i]]) ++z[i];
        if (i+z[i]>right) {left=i; right=i+z[i];}
    }
    return z;
}

#include <bits/stdc++.h>
#include <cassert>
using namespace std;

struct Trie {
    struct Node {
        array<int,26> next;
        int passing=0, ending=0;
        Node() {next.fill(-1);}
    };
    vector<Node> nodes{Node()};
    static bool valid(const string& word) {
        return all_of(word.begin(),word.end(),[](char c){return 'a'<=c && c<='z';});
    }
    bool insert(const string& word) {
        if (!valid(word)) return false;
        int vertex=0; ++nodes[0].passing;
        for (char c : word) {
            int letter=c-'a';
            if (nodes[vertex].next[letter]==-1) {
                int next=nodes.size(); nodes.emplace_back();
                nodes[vertex].next[letter]=next;
            }
            vertex=nodes[vertex].next[letter]; ++nodes[vertex].passing;
        }
        ++nodes[vertex].ending; return true;
    }
    int locate(const string& word) const {
        if (!valid(word)) return -1;
        int vertex=0;
        for (char c : word) {
            vertex=nodes[vertex].next[c-'a']; if (vertex==-1) return -1;
        }
        return vertex;
    }
    int count(const string& word) const {
        int vertex=locate(word); return vertex==-1 ? 0 : nodes[vertex].ending;
    }
    int prefix_count(const string& prefix) const {
        int vertex=locate(prefix); return vertex==-1 ? 0 : nodes[vertex].passing;
    }
    bool erase(const string& word) {
        if (!count(word)) return false;
        int vertex=0; --nodes[0].passing;
        for (char c : word) {vertex=nodes[vertex].next[c-'a']; --nodes[vertex].passing;}
        --nodes[vertex].ending; return true;
    }
};

templates.example:
int main() {
    Trie dictionary; dictionary.insert("ab"); dictionary.insert("ab"); dictionary.insert("abc");
    assert(dictionary.count("ab")==2 && dictionary.prefix_count("ab")==3);
    assert(dictionary.erase("ab") && dictionary.count("ab")==1);
    assert(!dictionary.insert("A") && !dictionary.erase("x"));
}

