#include <bits/stdc++.h>
#include <cassert>
using namespace std;

constexpr long long KNAPSACK_NEG_INF=numeric_limits<long long>::lowest()/4;
struct Item { int weight; long long value; };
vector<long long> knapsack(int capacity,const vector<Item>& items,
                           bool unlimited=false,bool exact=false) {
    assert(capacity>=0);
    vector<long long> best(capacity+1,exact ? KNAPSACK_NEG_INF : 0);
    best[0]=0;
    for (auto item : items) {
        assert(item.weight>0); // 零重量的完全背包可能导致无界最优值。
        auto relax=[&](int current) {
            if (best[current-item.weight]!=KNAPSACK_NEG_INF)
                best[current]=max(best[current],best[current-item.weight]+item.value);
        };
        if (unlimited) for (int current=item.weight; current<=capacity; ++current) relax(current);
        else for (int current=capacity; current>=item.weight; --current) relax(current);
    }
    return best;
}

templates.example:
int main() {
    vector<Item> items={{2,3},{3,4}};
    assert(knapsack(4,items)[4]==4 && knapsack(4,items,true)[4]==6);
    assert(knapsack(1,items,false,true)[1]==KNAPSACK_NEG_INF);
}

