#include <bits/stdc++.h>
#include <cassert>
using namespace std;

vector<int> longest_increasing_subsequence(const vector<long long>& values,bool strict=true) {
    vector<long long> tails;
    vector<int> last_index,parent(values.size(),-1);
    for (int i=0; i<(int)values.size(); ++i) {
        int length=(strict ? lower_bound(tails.begin(),tails.end(),values[i])
                           : upper_bound(tails.begin(),tails.end(),values[i]))-tails.begin();
        if (length>0) parent[i]=last_index[length-1];
        if (length==(int)tails.size()) {tails.push_back(values[i]); last_index.push_back(i);}
        else {tails[length]=values[i]; last_index[length]=i;}
    }
    vector<int> indices;
    for (int i=last_index.empty() ? -1 : last_index.back(); i!=-1; i=parent[i]) indices.push_back(i);
    reverse(indices.begin(),indices.end());
    return indices;
}

templates.example:
int main() {
    auto indices=longest_increasing_subsequence({3,1,2,2,4});
    assert(indices.size()==3);
    assert(longest_increasing_subsequence({2,2,2},false).size()==3);
}
